// Localized prose for the appliance installs: the Unraid Community Applications template
// (DiscVault launcher) and the Home Assistant app. Facts verified against
// helmerzNL/unraid-community-apps (templates/discvault.xml, templates/discvault-beta.xml) and
// helmerzNL/home-assistant-addons (discvault/config.yaml, discvault/DOCS.md).
// Locale order: en, cs, da, de, el, es, fi, fr, hu, it, ja, ko, nl, no, pl, pt, sv, tr, uk, zh.

const order = [
  'en',
  'cs',
  'da',
  'de',
  'el',
  'es',
  'fi',
  'fr',
  'hu',
  'it',
  'ja',
  'ko',
  'nl',
  'no',
  'pl',
  'pt',
  'sv',
  'tr',
  'uk',
  'zh',
];

const row = (...values) => {
  if (values.length !== order.length) {
    throw new Error(`Expected ${order.length} localized values, received ${values.length}.`);
  }
  return Object.fromEntries(order.map((locale, index) => [locale, values[index]]));
};

